#!/usr/bin/env node
/**
 * tests/adversarial-m2-strip-isolation.js
 *
 * Empirical Adversarial Challenger Test Suite — Milestone 2 (R2)
 * Challenger: challenger_gtv_m2_2
 *
 * Focus Areas:
 * 1. Horizontal Shelf Translation (.strip) across boundaries (index 0, mid, last, 40px peek).
 * 2. Strict Isolation between Home 16:9 shelves (352x198px) and catalog 6-col grids (220x330px in 1728px safe width).
 * 3. Episode Rail (#details-episodes-rail) in Details view retains flex layout and 320x180 episode dimensions.
 * 4. Boundary Reversal, Dynamic Re-rendering, and Rapid Traversal Stress.
 */

'use strict';

const fs = require('fs');
const path = require('path');
const assert = require('assert');

// 1. Resolve JSDOM
let JSDOM;
try {
  JSDOM = require('jsdom').JSDOM;
} catch (e1) {
  try {
    JSDOM = require('/home/prem/monkeytype/monkeytype/node_modules/.pnpm/jsdom@27.4.0_supports-color@10.2.2/node_modules/jsdom').JSDOM;
  } catch (e2) {
    try {
      JSDOM = require('/home/prem/Documents/movies/netflix/node_modules/jsdom').JSDOM;
    } catch (e3) {
      console.error('FATAL: JSDOM module could not be resolved:', e1.message);
      process.exit(1);
    }
  }
}

// 2. Terminal Styling
const C = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  cyan: '\x1b[36m',
  yellow: '\x1b[33m',
  gray: '\x1b[90m'
};

let totalChecks = 0;
let passedChecks = 0;
let failedChecks = 0;
const failureList = [];

async function check(suiteName, checkName, testFn) {
  totalChecks++;
  const idStr = totalChecks.toString().padStart(2, '0');
  const label = `[ADV-GTV-M2-2-${idStr}] [${suiteName}] ${checkName}`;
  const start = Date.now();
  try {
    await testFn();
    passedChecks++;
    const duration = Date.now() - start;
    console.log(`  ${C.green}✓ PASS${C.reset} ${label} ${C.gray}(${duration}ms)${C.reset}`);
  } catch (err) {
    failedChecks++;
    const duration = Date.now() - start;
    console.log(`  ${C.red}✗ FAIL${C.reset} ${label} ${C.gray}(${duration}ms)${C.reset}`);
    console.error(`      ${C.red}Defect: ${err.message}${C.reset}`);
    failureList.push({ label, error: err.message, stack: err.stack });
  }
}

/**
 * Creates DOM environment loading index.html, tokens, components, layout, and JavaScript controllers.
 */
function createTestDom(route = 'home') {
  const rootDir = path.resolve(__dirname, '..');
  const htmlPath = path.join(rootDir, 'app/index.html');
  const html = fs.readFileSync(htmlPath, 'utf8');

  const dom = new JSDOM(html, {
    url: 'http://localhost/#' + route,
    runScripts: 'outside-only',
    pretendToBeVisual: true
  });
  const { window } = dom;

  // Polyfill scroll methods
  if (!window.Element.prototype.scrollTo) {
    window.Element.prototype.scrollTo = function (options) {
      if (typeof options === 'object') {
        if (options.left !== undefined) this.scrollLeft = options.left;
        if (options.top !== undefined) this.scrollTop = options.top;
      }
    };
  }
  if (!window.Element.prototype.scrollIntoView) {
    window.Element.prototype.scrollIntoView = function () {};
  }

  // Load scripts into window context
  const scriptsToLoad = [
    'app/js/config.js',
    'app/js/services/tmdb.js',
    'app/js/navigation.js',
    'app/js/views/home.js',
    'app/js/views/catalog.js',
    'app/js/views/search.js',
    'app/js/views/details.js',
    'app/js/app.js'
  ];

  for (const relPath of scriptsToLoad) {
    const fullPath = path.join(rootDir, relPath);
    if (fs.existsSync(fullPath)) {
      const code = fs.readFileSync(fullPath, 'utf8');
      window.eval(code);
    }
  }

  return dom;
}

