    assert.strictEqual(card.className, 'card-episode', 'Episode card class must be strictly .card-episode');
    assert.strictEqual(card.classList.contains('card'), false, 'Episode card must NOT contain class .card');
    assert.strictEqual(card.classList.contains('card-poster'), false, 'Episode card must NOT contain class .card-poster');

    const media = card.querySelector('.episode-media');
    assert.ok(media, 'Card must have .episode-media');
    const title = card.querySelector('.episode-title');
    assert.strictEqual(title.textContent, '3. The Trail of Sand');
  });

  await check('DetailsRail', 'Focusing .card-episode never causes HomeVC strip translation on episode rail', () => {
    const dom = createTestDom('details');
    const { window } = dom;
    const HomeVC = window.HomeViewController;
    HomeVC.init();

    const rail = window.document.getElementById('details-episodes-rail');
    const firstEp = rail.querySelector('.card-episode');
    assert.ok(firstEp, 'Episode card must exist');

    // Handle focus on first episode
    HomeVC.handleElementFocus(firstEp);
    assert.strictEqual(rail.style.transform, '', 'Episode rail style.transform must NOT be modified');

    // Simulate D-pad focus on second episode
    const secondEp = rail.querySelectorAll('.card-episode')[1];
    HomeVC.handleElementFocus(secondEp);
    assert.strictEqual(rail.style.transform, '', 'Episode rail style.transform must remain empty on all episodes');
  });

  await check('DetailsRail', 'DetailsViewController.renderEpisodes updates rail dynamically preserving structure', () => {
    const dom = createTestDom('details');
    const { window } = dom;
    const DetailsVC = window.DetailsViewController;
    assert.ok(DetailsVC, 'DetailsViewController must exist');

    const mockEpisodes = [
      { id: 901, episode_number: 1, name: 'Pilot Redux', runtime: 60, overview: 'First ep' },
      { id: 902, episode_number: 2, name: 'Second Step', runtime: 58, overview: 'Second ep' },
      { id: 903, episode_number: 3, name: 'Third Climax', runtime: 64, overview: 'Third ep' }
    ];

    DetailsVC.renderEpisodes(mockEpisodes, 2);

    const rail = window.document.getElementById('details-episodes-rail');
    const newCards = rail.querySelectorAll('.card-episode');
    assert.strictEqual(newCards.length, 3, 'Must render 3 updated episode cards');
    assert.strictEqual(newCards[0].querySelector('.episode-title').textContent, '1. Pilot Redux');
    assert.strictEqual(newCards[1].querySelector('.episode-title').textContent, '2. Second Step');
    assert.strictEqual(newCards[2].querySelector('.episode-title').textContent, '3. Third Climax');
    assert.strictEqual(rail.style.transform, '', 'Rail must have zero transform');
  });

  // ==========================================================================
  // SUITE 5: CROSS-VIEW DYNAMIC RE-RENDERING & SAFE AREA GEOMETRY
  // ==========================================================================
  console.log(`\n${C.bold}▶ SUITE 5: Cross-View Layout Geometry & Stress Traversal${C.reset}`);

  await check('Stress', 'View switching Home -> Movies -> Series -> Search -> Details -> Home retains DOM integrity', () => {
    const dom = createTestDom('home');
    const { window } = dom;
    const app = window.CinejoyApp;
    assert.ok(app, 'CinejoyApp must exist');
    app.init();

    const views = ['movies', 'series', 'search', 'details', 'home'];
    for (const v of views) {
      app.switchView(v);
      const active = window.document.querySelector('.view.active');
      assert.ok(active, `A view must be active after switching to ${v}`);
      assert.strictEqual(active.id, 'view-' + v, `Active view must be view-${v}`);
    }

    // Verify Home shelves still have .strip
    const homeStrips = window.document.querySelectorAll('#view-home .strip');
    assert.ok(homeStrips.length > 0, 'Home view must retain .strip containers');

    // Verify Movies grid still has .content-grid-6col and NO .strip
    const moviesGrid = window.document.querySelector('#view-movies .content-grid-6col');
    assert.ok(moviesGrid, 'Movies grid must retain .content-grid-6col');
    assert.strictEqual(moviesGrid.classList.contains('strip'), false, 'Movies grid must NOT acquire .strip');

    // Verify Details episode rail still has .shelf-rail and NO .strip
    const epRail = window.document.getElementById('details-episodes-rail');
    assert.ok(epRail, 'Details episode rail must exist');
    assert.strictEqual(epRail.classList.contains('strip'), false, 'Details episode rail must NOT acquire .strip');
  });

  await check('Stress', 'Safe area width constraint (1728px usable) mathematically verified against 6 columns', () => {
    // Canvas: 1920px. 5% TV safe = 96px left + 96px right = 192px total margin.
    const canvasWidth = 1920;
    const safeMarginX = 96;
    const usableWidth = canvasWidth - (2 * safeMarginX); // 1728px
    assert.strictEqual(usableWidth, 1728, 'Usable width must be 1728px');

    // Grid: 6 columns of 220px = 1320px. 5 gaps of 24px = 120px. Total card width = 1440px.
    const colCount = 6;
    const cardWidth = 220;
    const colGap = 24;
    const totalRequiredWidth = (colCount * cardWidth) + ((colCount - 1) * colGap);
    assert.strictEqual(totalRequiredWidth, 1440, '6 columns of 220px cards with 24px gaps require 1440px');

    // 1440px <= 1728px usable width -> fits comfortably with 288px margin slack across grid tracks!
    assert.ok(totalRequiredWidth <= usableWidth, `Total required width (${totalRequiredWidth}px) fits within usable width (${usableWidth}px)`);
  });

  // Summary
  console.log(`\n${C.bold}${C.cyan}========================================================================${C.reset}`);
  console.log(`${C.bold}  TEST RESULTS SUMMARY${C.reset}`);
  console.log(`  Total Checks Executed:  ${totalChecks}`);
  console.log(`  Passed Checks:          ${C.green}${passedChecks}${C.reset}`);
  console.log(`  Failed Checks:          ${failedChecks > 0 ? C.red : C.green}${failedChecks}${C.reset}`);
  console.log(`${C.bold}${C.cyan}========================================================================${C.reset}\n`);

  if (failedChecks > 0) {
    console.error(`${C.bold}${C.red}VERDICT: REJECT (${failedChecks} failures)${C.reset}\n`);
    for (const f of failureList) {
      console.error(`- ${f.label}: ${f.error}`);
    }
    process.exit(1);
  } else {
    console.log(`${C.bold}${C.green}VERDICT: APPROVE (100% of ${totalChecks} empirical checks passed)${C.reset}\n`);
    process.exit(0);
  }
}

runAllSuites().catch(err => {
  console.error('Unhandled fatal error in test execution:', err);
  process.exit(1);
});

